    wanderX: x, wanderY: y, facing: 1, anim: Math.random() * 10,
    aggroed: false, deadT: 0, chase: false
  };
}

export function populateEnemies(world, opts = {}) {
  const rng = makeRng(`mobs:${world.regionId}:${world.mode}:${Date.now()}`);
  const enemies = [];
