65: function setTile(world, x, y, type, variant) {
66:   if (!inBounds(world, x, y)) return;
67:   const t = world.tiles[idx(world.size, x, y)];
68:   if (!t) return;
69:   t.type = type;
70:   if (variant != null) t.variant = variant;
71:   if (type === 'water' || type === 'void') t.blocked = true;
72: }
