88: function markPath(world, x1, y1, x2, y2, width = 1.5) {
89:   const steps = Math.ceil(Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1)) * 2);
90:   for (let i = 0; i <= steps; i++) {
91:     const t = i / steps;
92:     // slight winding for a hand-painted feel
93:     const wobble = Math.sin(t * Math.PI * 3) * 0.9;
94:     const x = x1 + (x2 - x1) * t + wobble * 0.35;
95:     const y = y1 + (y2 - y1) * t - wobble * 0.35;
96:     markDisc(world, x + 0.5, y + 0.5, width, 'path', tile => tile.type !== 'water');
97:   }
98: }
