100: function propBlocked(world, x, y, radius = 0.18) {
101:   for (const p of world.blockingProps) {
102:     if (Math.abs(p.x - x) > 2 || Math.abs(p.y - y) > 2) continue;
103:     if (Math.hypot(p.x - x, p.y - y) < p.block + radius) return true;
104:   }
105:   return false;
