110:   if (!inBounds(world, Math.floor(x), Math.floor(y))) return null;
111:   if (world.tiles[idx(world.size, Math.floor(x), Math.floor(y))]?.type === 'water') return null;
112:   const p = {
113:     pid: uid('p'), type, kind: def.kind, x, y,
114:     block: options.nonBlocking ? 0 : def.block, height: def.height,
115:     variant: rng.int(0, 999), flip: rng.chance(0.5), scale: options.scale || (0.9 + rng.next() * 0.25),
116:     fixed: !!options.fixed, glow: options.glow || null
117:   };
118:   world.props.push(p);
