340: export function isBlocked(world, x, y, radius = 0.22) {
341:   if (x < 1.1 || y < 1.1 || x > world.size - 1.1 || y > world.size - 1.1) return true;
342:   const tx = Math.floor(x), ty = Math.floor(y);
343:   const t = world.tiles[idx(world.size, clamp(tx, 0, world.size - 1), clamp(ty, 0, world.size - 1))];
344:   if (!t) return true;
345:   if (t.blocked || t.type === 'water' || t.type === 'void') return true;
346:   // check all tiles under the collision circle
347:   if (isTileBlocked(world, x + radius, y) || isTileBlocked(world, x - radius, y)
348:     || isTileBlocked(world, x, y + radius) || isTileBlocked(world, x, y - radius)) return true;
349:   return propBlocked(world, x, y, radius);
