324:     const steps = Math.max(8, Math.ceil(radius * 8));
325:     for (let i = 0; i < steps; i++) {
326:       const a = (i / steps) * Math.PI * 2;
327:       const x = origin.x + Math.cos(a) * radius;
328:       const y = origin.y + Math.sin(a) * radius;
329:       if (x < 1.2 || y < 1.2 || x > world.size - 1.2 || y > world.size - 1.2) continue;
330:       if (!isBlocked(world, x, y, 0.26)) return { x, y };
331:     }
332:   }
333:   return { x: world.village[0], y: world.village[1] + 2 };
