272:   for (const n of npcList) {
273:     world.npcs.push({
274:       ...n,
275:       x: clamp(vx + n.dx, 2, size - 3),
276:       y: clamp(vy + n.dy, 2, size - 3),
277:       facing: 1, anim: Math.random() * 10
278:     });
279:   }
280: 
281:   placeVillage(world, region, rng);
282:   placeLair(world, region, rng);
283: 
284:   // random scenery
285:   const propCount = Math.floor(size * 2.4);
286:   for (let i = 0; i < propCount * 3 && world.props.length < propCount; i++) {
287:     const type = rng.pick(region.props);
288:     const x = 1.4 + rng.next() * (size - 2.8);
289:     const y = 1.4 + rng.next() * (size - 2.8);
290:     if (!regionClears(world, x, y, rng, { villageClear: 7.2 })) continue;
291:     if (Math.hypot(x - world.lair[0], y - world.lair[1]) < 4.5) continue;
292:     tryPlaceProp(world, rng, type, x, y);
293:   }
294: 
295:   // extra roadside details
296:   for (let i = 0; i < 18; i++) {
297:     const type = rng.pick(['flowers', 'bush', 'stump', 'rubble', 'bone', 'signpost'].filter(t => region.props.includes(t) || Math.random() < 0.3));
298:     if (!type) continue;
299:     const x = 1.5 + rng.next() * (size - 3);
300:     const y = 1.5 + rng.next() * (size - 3);
301:     if (!regionClears(world, x, y, rng, { villageClear: 6.4 })) continue;
302:     tryPlaceProp(world, rng, type, x, y, { nonBlocking: true, scale: 0.8 + rng.next() * 0.4 });
