314:   // Scenery is placed procedurally and can overlap the configured spawn
315:   // (or the dungeon threshold). Nudge the spawn to the nearest walkable tile
316:   // so the player can never load inside a tree, house or pool of water.
317:   world.spawn = findSafeSpawn(world, world.spawn);
318:   return world;
319: }
