234:     greendale: [26, 7, 3.3], ironcrag: [7, 26, 2.6], venomwood: [27, 6, 3.6], mistgrave: [7, 27, 3.2],
235:     frostpeak: [27, 7, 3.4], sunscorch: [7, 28, 2.8], ashen: [28, 7, 3.1], tower: [7, 7, 2.6]
236:   }[regionId];
