254:   markPath(world, vx, vy, world.lair[0] - 2, world.lair[1] - 2, 1.3);
255:   markPath(world, vx - 5, vy + 1, size - 4, 4, 0.85);
256:   markPath(world, 4, vy - 3, size - 4, size - 4, 0.85);
