385:   // ------------------------------------------------------------
386:   // PLAYER COMBAT
387:   // ------------------------------------------------------------
388:   nearestEnemy(maxRange = 99) {
389:     let best = null, bestD = maxRange;
390:     for (const e of this.world.enemies) {
391:       if (!e.alive) continue;
392:       const d = Math.hypot(e.x - this.player.x, e.y - this.player.y);
393:       if (d < bestD) { bestD = d; best = e; }
394:     }
395:     return best;
396:   }
