398:   attackPressed() {
399:     if (this.transitioning || this.player.dead) return;
400:     const stats = this.state.stats();
401:     const near = this.nearestEnemy(stats.attackRange + 0.4);
402:     if (near) this.target = near;
403:     this.normalAttack(false);
404:   }
405: 
406:   normalAttack(auto = false) {
407:     const stats = this.state.stats();
408:     if (this.attackCd > 0) return;
409:     if (!this.target || !this.target.alive) {
410:       const near = this.nearestEnemy(stats.attackRange + 0.35);
411:       if (!near) {
412:         if (!auto) this.sfx.play('error');
413:         return;
414:       }
415:       this.target = near;
416:     }
417:     const d = Math.hypot(this.target.x - this.player.x, this.target.y - this.player.y);
418:     if (d > stats.attackRange + 0.35) {
419:       if (!auto) this.input.moveTarget = { x: this.target.x, y: this.target.y };
420:       return;
421:     }
422:     this.attackCd = stats.attackInterval;
423:     this.player.attackAnim = 1;
424:     this.player.facing = (this.target.x - this.target.y) > (this.player.x - this.player.y) ? 1 : -1;
425:     this.sfx.play('attack');
426:     const dmg = this.rollDamage(1.0);
427:     if (this.state.char.classId === 'warrior') {
428:       this.addEffect({ type: 'slash', x: this.target.x, y: this.target.y, color: '#ffe0a0', life: 0.25, maxLife: 0.25 });
429:       this.applyDamage(this.target, dmg.amount, dmg.crit);
430:     } else {
431:       this.spawnProjectile({
432:         type: this.state.char.classId === 'archer' ? 'arrow' : 'fire',
433:         target: this.target, amount: dmg.amount, crit: dmg.crit,
434:         speed: this.state.char.classId === 'archer' ? 14 : 9,
435:         color: this.state.char.classId === 'archer' ? '#e8dcc0' : '#ffb23e'
436:       });
437:     }
438:   }
439: 
440:   skillPressed() {
441:     if (this.transitioning || this.player.dead) return;
442:     const stats = this.state.stats();
443:     const skill = this.state.cls.skill;
444:     if (this.skillCd > 0) {
445:       Events.emit('toast', { msg: `${skill.name} is on cooldown (${this.skillCd.toFixed(1)}s).`, type: 'warn', small: true });
446:       this.sfx.play('error');
447:       return;
448:     }
449:     if (this.state.char.mana < skill.mana) {
450:       Events.emit('toast', { msg: 'Not enough mana.', type: 'warn', small: true });
451:       this.sfx.play('error');
452:       return;
453:     }
454:     this.state.char.mana -= skill.mana;
455:     this.skillCd = skill.cooldown;
456:     this.player.casting = 1;
457:     this.sfx.play('skill');
458: 
459:     const level = this.state.char.skillLevel;
460:     const mult = skill.multiplier * (1 + (level - 1) * 0.16);
461:     const radius = skill.radius + (level - 1) * 0.06;
462:     const targets = this.world.enemies.filter(e => e.alive && Math.hypot(e.x - this.player.x, e.y - this.player.y) <= radius);
463:     this.addEffect({ type: 'ring', x: this.player.x, y: this.player.y, radius, color: skill.id === 'nova' ? '#79d6ff' : skill.id === 'whirlwind' ? '#ffb23e' : '#a8e07a', life: 0.5, maxLife: 0.5, width: 4 });
464:     this.addEffect({ type: 'burst', x: this.player.x, y: this.player.y, color: '#ffe08a', life: 0.55, maxLife: 0.55 });
465: 
466:     if (skill.id === 'whirlwind') {
467:       for (const e of targets) {
468:         const dmg = this.rollDamage(mult);
469:         this.applyDamage(e, dmg.amount, dmg.crit);
470:       }
471:       if (!targets.length) Events.emit('toast', { msg: 'Whirlwind strikes empty air.', type: 'warn', small: true });
472:       this.screenShake = 4;
473:     } else if (skill.id === 'nova') {
474:       for (const e of targets) {
475:         const dmg = this.rollDamage(mult);
476:         this.applyDamage(e, dmg.amount, dmg.crit);
477:         e.stunUntil = Date.now() + 1200;
478:         this.addEffect({ type: 'burst', x: e.x, y: e.y, color: '#79d6ff', life: 0.4, maxLife: 0.4 });
479:       }
480:     } else {
481:       const volley = targets.slice(0, 6);
482:       if (!volley.length) {
483:         const t = this.nearestEnemy(radius + 2);
484:         if (t) volley.push(t);
485:       }
486:       for (const e of volley) {
487:         const dmg = this.rollDamage(mult);
488:         this.spawnProjectile({ type: 'arrow', target: e, amount: dmg.amount, crit: dmg.crit, speed: 18, color: '#d7ffb0' });
489:       }
490:       if (!volley.length) Events.emit('toast', { msg: 'Arrow Storm finds no target.', type: 'warn', small: true });
491:     }
492:     Events.emit('skillUsed', { skill, level });
493:   }
