495:   rollDamage(mult = 1) {
496:     const stats = this.state.stats();
497:     const variance = 0.9 + Math.random() * 0.2;
498:     const crit = Math.random() < stats.crit;
499:     let amount = stats.attack * mult * variance;
500:     if (crit) amount *= stats.critDamage;
501:     return { amount: Math.max(1, Math.round(amount)), crit };
502:   }
503: 
504:   applyDamage(enemy, amount, crit) {
505:     if (!enemy.alive) return;
506:     enemy.hp -= amount;
507:     enemy.hitFlash = 0.12;
508:     this.addEffect({
509:       type: 'dmg', x: enemy.x, y: enemy.y,
510:       text: crit ? `${fmt(amount)}!` : fmt(amount),
511:       color: crit ? '#ffd166' : '#ffe8d0', big: crit,
512:       dx: (Math.random() - 0.5) * 24, offset: Math.random() * 8,
513:       life: 0.85, maxLife: 0.85
514:     });
515:     this.sfx.play(crit ? 'crit' : 'hit');
516:     if (enemy.hp <= 0) this.killEnemy(enemy);
517:     Events.emit('enemyHit', { enemy, amount, crit });
518:   }
519: 
520:   spawnProjectile(opts) {
521:     this.projectiles.push({
522:       type: opts.type,
523:       x: this.player.x, y: this.player.y,
524:       target: opts.target, speed: opts.speed || 12,
525:       amount: opts.amount, crit: opts.crit,
526:       color: opts.color, life: 3
527:     });
528:   }
529: 
530:   updateProjectiles(dt) {
531:     for (const pr of [...this.projectiles]) {
532:       pr.life -= dt;
533:       if (!pr.target || !pr.target.alive || pr.life <= 0) {
534:         this.projectiles = this.projectiles.filter(p => p !== pr);
535:         continue;
536:       }
537:       const d = Math.hypot(pr.target.x - pr.x, pr.target.y - pr.y);
538:       if (d < 0.35) {
539:         this.applyDamage(pr.target, pr.amount, pr.crit);
540:         this.projectiles = this.projectiles.filter(p => p !== pr);
541:         continue;
542:       }
543:       const step = Math.min(d, pr.speed * dt);
544:       pr.x += (pr.target.x - pr.x) / d * step;
545:       pr.y += (pr.target.y - pr.y) / d * step;
546:     }
547:   }
