766:   teleportCostTo(regionId, dungeonId = null) {
767:     const from = this.currentDungeon ? this.currentDungeon.region : this.state.char.region;
768:     if (dungeonId) {
769:       const d = DUNGEONS.find(x => x.id === dungeonId);
770:       return d ? d.cost : CONFIG.teleport.dungeonMin;
771:     }
772:     if (regionId === from) return CONFIG.teleport.same;
773:     return this.state.teleportCost(from, regionId);
774:   }
775: 
776:   travelTo(regionId, opts = {}) {
777:     if (this.transitioning) return false;
778:     if (!REGIONS[regionId]) return false;
779:     const from = this.currentDungeon ? this.currentDungeon.region : this.state.char.region;
780:     if (REGION_ORDER.indexOf(from) > 1 && regionId !== 'greendale') {
781:       Events.emit('toast', { msg: 'This leyline only returns you to Greendale.', type: 'info' });
782:       return false;
783:     }
784:     if (regionId === from && !this.currentDungeon && opts.force !== true) {
785:       // fast travel within the same region: still costs the same-region fee
786:     }
787:     const cost = this.teleportCostTo(regionId, opts.dungeonId);
788:     if (cost > 0 && !this.state.spendGold(cost, 'teleport', `${regionId}${opts.dungeonId ? ':' + opts.dungeonId : ''}`)) {
789:       Events.emit('toast', { msg: `Not enough gold. Teleport costs ${fmt(cost)}.`, type: 'warn' });
790:       this.sfx.play('error');
791:       return false;
792:     }
793:     if (cost > 0) {
794:       Events.emit('toast', { msg: `Teleported for ${fmt(cost)} gold.`, type: 'info', small: true });
795:     }
796:     this.enterRegion(regionId, { dungeonId: opts.dungeonId, initial: false });
797:     return true;
798:   }
799: 
800:   enterDungeon(dungeonId) {
801:     const d = DUNGEONS.find(x => x.id === dungeonId);
802:     if (!d) return false;
803:     if (this.state.char.level + 3 < d.level) {
804:       Events.emit('toast', { msg: `Recommended level ${d.level}. You can still enter, but be careful.`, type: 'warn' });
