940:   handleTap(sx, sy) {
941:     const world = this.world;
942:     if (!world) return;
943:     // enemy click (screen distance)
944:     let picked = null, pickedD = 42;
945:     for (const e of world.enemies) {
946:       if (!e.alive) continue;
947:       const s = this.renderer.worldToScreen(e.x, e.y);
948:       const d = Math.hypot(s.x - sx, s.y - (sy + 18));
949:       if (d < pickedD + (e.boss ? 26 : 0)) { picked = e; pickedD = d; }
950:     }
951:     if (picked) {
952:       this.target = picked;
953:       const stats = this.state.stats();
954:       const d = Math.hypot(picked.x - this.player.x, picked.y - this.player.y);
955:       if (d > stats.attackRange + 0.2) {
956:         this.input.moveTarget = { x: picked.x, y: picked.y };
957:       } else {
958:         this.normalAttack(false);
959:       }
960:       return;
961:     }
962:     // npc click
963:     for (const npc of world.npcs) {
964:       const s = this.renderer.worldToScreen(npc.x, npc.y);
965:       if (Math.hypot(s.x - sx, s.y - (sy + 20)) < 34) {
966:         const d = Math.hypot(npc.x - this.player.x, npc.y - this.player.y);
967:         if (d < 2.6) {
