969:         } else {
970:           this.input.moveTarget = { x: npc.x + 0.9, y: npc.y + 0.9 };
971:         }
972:         return;
973:       }
974:     }
975:     // node / chest click
976:     for (const node of world.nodes) {
977:       if (node.respawnAt > Date.now()) continue;
978:       const s = this.renderer.worldToScreen(node.x, node.y);
979:       if (Math.hypot(s.x - sx, s.y - (sy + 12)) < 28) {
980:         const d = Math.hypot(node.x - this.player.x, node.y - this.player.y);
981:         if (d < 2.1) this.gatherNode(node);
982:         else this.input.moveTarget = { x: node.x, y: node.y };
983:         return;
984:       }
985:     }
986:     // ground move
987:     const w = this.renderer.screenToWorld(sx, sy);
988:     if (w.x > 1 && w.y > 1 && w.x < world.size - 1 && w.y < world.size - 1 && !isBlocked(world, w.x, w.y, 0.2)) {
989:       this.input.moveTarget = { x: w.x, y: w.y };
990:       this.target = null;
991:     }
