  const cost = this.currentDungeon ? CONFIG.teleport.same : 0;
  if (cost && !this.state.spendGold(cost, 'teleport', 'Return to hub')) {
    Events.emit('toast', { msg: 'Not enough gold to return.', type: 'warn' });
