node --experimental-default-type=module <<'EOF'
import { REGIONS, REGION_ORDER, DUNGEONS } from './src/data.js';
import { buildWorld, populateEnemies, isBlocked } from './src/world.js';
for (const id of REGION_ORDER) {
  const w = buildWorld(id);
  populateEnemies(w);
  const q = [[Math.floor(w.spawn.x), Math.floor(w.spawn.y)]], seen = new Set();
  const key = (x, y) => y * w.size + x;
  for (let i = 0; i < q.length; i++) {
    const [x, y] = q[i];
    if (x < 1 || y < 1 || x >= w.size - 1 || y >= w.size - 1) continue;
    const k = key(x, y);
    if (seen.has(k) || isBlocked(w, x + .5, y + .5, .2)) continue;
    seen.add(k);
    q.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]);
  }
  const types = new Set(w.tiles.map(t => t.type));
  const pond = w.tiles.filter(t => t.type === 'water').length;
  console.log('region', id, JSON.stringify({size:w.size, spawn:w.spawn, spawnBlocked:isBlocked(w,w.spawn.x,w.spawn.y,.25), reachable:seen.size, tiles:w.tiles.length, waterTiles:pond, terrain:[...types], nodes:w.nodes.length, npcs:w.npcs.map(n=>n.name)}));
}
for (const d of DUNGEONS) {
  const w = buildWorld(d.region, {dungeonId:d.id});
  populateEnemies(w);
  const boss = w.enemies.find(e => e.boss);
  const spawnD = Math.hypot(w.spawn.x - boss.x, w.spawn.y - boss.y);
  console.log('dungeon', d.id, JSON.stringify({region:d.region, spawn:w.spawn, spawnBlocked:isBlocked(w,w.spawn.x,w.spawn.y,.25), boss:{x:boss.x,y:boss.y}, bossBlocked:isBlocked(w,boss.x,boss.y,.25), spawnToBoss:spawnD, mobs:w.enemies.length, bossReachableArea:w.enemies.filter(e=>e.boss).length}));
}
EOF

